INSERT INTO reports.html_reports (report_id, file_name, created_at, html_content)
SELECT report_id, file_name, created_at, html_content FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM reports.html_reports);
DROP TABLE _stg_load;

SELECT setval('reports.html_reports_report_id_seq', GREATEST((SELECT COALESCE(max(report_id),0) FROM reports.html_reports),1), (SELECT count(*) FROM reports.html_reports) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'reports' AND c.relname = 'html_reports'
          AND con.conname = 'html_reports_pkey') THEN
        ALTER TABLE ONLY reports.html_reports
    ADD CONSTRAINT html_reports_pkey PRIMARY KEY (report_id);
    END IF;
END $do$;
